import{_ as e,o as t,c as r,a5 as a}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"程序使用环境及相关说明","description":"","frontmatter":{"标题":"924-批量Excel加密工具-为excel添加打开密码","日期":"2026-04-25T00:00:00.000Z","修改日期":"2026-05-28T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["EXCEL批处理"],"标签":["Excel加密工具","Excel密码保护","Excel打开密码","Excel批量加密","Excel文件加密","Excel查看密码","Excel编辑密码","Office加密工具","WPS加密","双重密码保护","批量Excel加密","批量加密工具"]},"headers":[{"level":2,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":2,"title":"设置密码","slug":"设置密码","link":"#设置密码","children":[]},{"level":2,"title":"设置处理选项","slug":"设置处理选项","link":"#设置处理选项","children":[]},{"level":2,"title":"密码类型说明","slug":"密码类型说明","link":"#密码类型说明","children":[{"level":3,"title":"查看密码（打开密码）","slug":"查看密码-打开密码","link":"#查看密码-打开密码","children":[]},{"level":3,"title":"编辑密码（修改密码）","slug":"编辑密码-修改密码","link":"#编辑密码-修改密码","children":[]},{"level":3,"title":"双重密码保护","slug":"双重密码保护","link":"#双重密码保护","children":[]}]},{"level":2,"title":"处理引擎说明","slug":"处理引擎说明","link":"#处理引擎说明","children":[{"level":3,"title":"自动检测（默认）","slug":"自动检测-默认","link":"#自动检测-默认","children":[]},{"level":3,"title":"Microsoft Office","slug":"microsoft-office","link":"#microsoft-office","children":[]},{"level":3,"title":"WPS Office","slug":"wps-office","link":"#wps-office","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[{"level":3,"title":"适用人群","slug":"适用人群","link":"#适用人群","children":[]},{"level":3,"title":"解决的痛点","slug":"解决的痛点","link":"#解决的痛点","children":[]},{"level":3,"title":"实际使用场景示例","slug":"实际使用场景示例","link":"#实际使用场景示例","children":[]},{"level":3,"title":"场景1：年底加密所有财务报表","slug":"场景1-年底加密所有财务报表","link":"#场景1-年底加密所有财务报表","children":[]},{"level":3,"title":"场景2：批量加密后保存到新位置","slug":"场景2-批量加密后保存到新位置","link":"#场景2-批量加密后保存到新位置","children":[]},{"level":3,"title":"场景3：单文件快速加密","slug":"场景3-单文件快速加密","link":"#场景3-单文件快速加密","children":[]},{"level":3,"title":"数据存储位置","slug":"数据存储位置","link":"#数据存储位置","children":[]}]},{"level":2,"title":"常见问题","slug":"常见问题","link":"#常见问题","children":[{"level":3,"title":"问题1：程序提示未检测到Office或WPS，无法加密","slug":"问题1-程序提示未检测到office或wps-无法加密","link":"#问题1-程序提示未检测到office或wps-无法加密","children":[]},{"level":3,"title":"问题2：加密后的文件打开显示密码错误","slug":"问题2-加密后的文件打开显示密码错误","link":"#问题2-加密后的文件打开显示密码错误","children":[]},{"level":3,"title":"问题3：勾选了穿透子文件夹但没有处理子文件夹中的文件","slug":"问题3-勾选了穿透子文件夹但没有处理子文件夹中的文件","link":"#问题3-勾选了穿透子文件夹但没有处理子文件夹中的文件","children":[]},{"level":3,"title":"问题4：输出文件夹中文件数量和原文件夹不一样","slug":"问题4-输出文件夹中文件数量和原文件夹不一样","link":"#问题4-输出文件夹中文件数量和原文件夹不一样","children":[]},{"level":3,"title":"问题5：使用自动检测引擎加密失败","slug":"问题5-使用自动检测引擎加密失败","link":"#问题5-使用自动检测引擎加密失败","children":[]}]}],"relativePath":"md/EXCEL批处理/924-批量Excel加密工具-为excel添加打开密码.md","filePath":"md/EXCEL批处理/924-批量Excel加密工具-为excel添加打开密码.md"}'),i={name:"md/EXCEL批处理/924-批量Excel加密工具-为excel添加打开密码.md"};function o(n,l,s,c,h,p){return t(),r("div",null,[...l[0]||(l[0]=[a('<p>批量Excel加密工具，支持一键批量加密Excel文件。支持设置查看密码（打开密码）和编辑密码（修改密码），可同时添加两种密码保护。告别手动一个个加密Excel，适用于敏感数据保护、企业文档管理等场景，适用于Windows系统，需要Microsoft Office或WPS配合使用。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-19.png" alt=""></p><h2 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h2><ul><li>批量处理文件夹中的所有Excel文件（.xls、.xlsx、.xlsm格式）</li><li>支持设置查看密码（打开密码）和编辑密码（修改密码）</li><li>可同时添加两种密码，实现双重保护</li><li><strong>多引擎自动适配</strong>：自动检测你电脑上安装的是Microsoft Office还是WPS，优先使用最稳定的方式进行加密。</li><li>支持穿透子文件夹处理</li><li><strong>原文件夹结构保持</strong>：勾选保持原文件夹结构选项后，加密后的文件会保存在同名加密文件夹中，目录层级完全一致。</li><li>支持拖拽文件或文件夹到输入框</li><li>支持单独处理单个Excel文件</li></ul><h2 id="设置密码" tabindex="-1"><strong>设置密码</strong> <a class="header-anchor" href="#设置密码" aria-label="Permalink to &quot;**设置密码**&quot;">​</a></h2><ul><li>勾选”添加查看密码”并输入查看密码（打开文件需要）</li><li>勾选”添加编辑密码”并输入编辑密码（修改文件需要）</li><li>可同时勾选两个，实现双重密码保护</li><li>可勾选”显示密码”查看输入的内容</li></ul><ol><li></li></ol><h2 id="设置处理选项" tabindex="-1"><strong>设置处理选项</strong> <a class="header-anchor" href="#设置处理选项" aria-label="Permalink to &quot;**设置处理选项**&quot;">​</a></h2><ul><li>选择处理引擎：自动检测、Office、WPS</li><li>勾选”穿透子文件夹”可递归处理子文件夹</li><li>勾选”保持原文件夹结构”可保留目录层级</li></ul><h2 id="密码类型说明" tabindex="-1">密码类型说明 <a class="header-anchor" href="#密码类型说明" aria-label="Permalink to &quot;密码类型说明&quot;">​</a></h2><h3 id="查看密码-打开密码" tabindex="-1">查看密码（打开密码） <a class="header-anchor" href="#查看密码-打开密码" aria-label="Permalink to &quot;查看密码（打开密码）&quot;">​</a></h3><ul><li>打开Excel文件时需要输入的密码</li><li>不知道密码则无法打开文件，无法查看任何内容</li><li>适用于需要严格保密的文件</li></ul><h3 id="编辑密码-修改密码" tabindex="-1">编辑密码（修改密码） <a class="header-anchor" href="#编辑密码-修改密码" aria-label="Permalink to &quot;编辑密码（修改密码）&quot;">​</a></h3><ul><li>可以正常打开文件查看内容</li><li>但修改、保存或打印时需要输入密码</li><li>适用于允许查看但不允许修改的文件</li></ul><h3 id="双重密码保护" tabindex="-1">双重密码保护 <a class="header-anchor" href="#双重密码保护" aria-label="Permalink to &quot;双重密码保护&quot;">​</a></h3><ul><li>同时设置查看密码和编辑密码</li><li>打开文件时需要输入查看密码</li><li>修改文件时需要输入编辑密码</li><li>提供最高级别的保护</li></ul><h2 id="处理引擎说明" tabindex="-1">处理引擎说明 <a class="header-anchor" href="#处理引擎说明" aria-label="Permalink to &quot;处理引擎说明&quot;">​</a></h2><h3 id="自动检测-默认" tabindex="-1">自动检测（默认） <a class="header-anchor" href="#自动检测-默认" aria-label="Permalink to &quot;自动检测（默认）&quot;">​</a></h3><p>程序会自动检测系统中安装的办公软件（优先WPS，其次Office），选择可用的引擎进行处理。</p><h3 id="microsoft-office" tabindex="-1">Microsoft Office <a class="header-anchor" href="#microsoft-office" aria-label="Permalink to &quot;Microsoft Office&quot;">​</a></h3><p>强制使用Microsoft Excel进行加密操作。需要安装Microsoft Excel。</p><h3 id="wps-office" tabindex="-1">WPS Office <a class="header-anchor" href="#wps-office" aria-label="Permalink to &quot;WPS Office&quot;">​</a></h3><p>强制使用WPS表格进行加密操作。需要安装WPS Office。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>重要提示：处理前请<strong>备份重要数据</strong>，防止误操作导致文件丢失。虽然程序设计为覆盖原文件或保存到新位置，但批量操作存在风险。</p><p>操作过程中<strong>不要关闭程序窗口</strong>，等待处理完成提示出现后再进行其他操作。</p><p>确认目标文件夹有<strong>足够空间</strong>存放输出文件（如果选择不覆盖原文件）。</p><p>首次使用建议<strong>先用少量文件测试</strong>，确认效果和输出位置符合预期后再批量处理。</p><p>如果程序无响应或处理卡住，可能是大文件处理较慢或加密引擎异常，耐心等待片刻或尝试重启程序。</p><p>加密密码<strong>区分大小写</strong>，输入时注意大小写是否正确。</p><p>如果电脑同时安装了Office和WPS，程序会自动选择一种引擎。如果加密失败，可以手动切换到另一种引擎重试。</p><h3 id="适用人群" tabindex="-1">适用人群 <a class="header-anchor" href="#适用人群" aria-label="Permalink to &quot;适用人群&quot;">​</a></h3><p>经常处理敏感Excel数据的<strong>财务人员</strong>，需要加密工资表、报表等重要文件。</p><p>对外发送Excel文件时需要保护内容的<strong>行政人员</strong>，防止信息泄露。</p><p>企业资料管理员需要对批量文件设置统一密码的<strong>管理人员</strong>。</p><p>需要批量加密合同、客户名单等文档的<strong>商务人员</strong>。</p><p>个人需要保护私人账目、密码本等Excel文件的<strong>普通用户</strong>。</p><hr><h3 id="解决的痛点" tabindex="-1">解决的痛点 <a class="header-anchor" href="#解决的痛点" aria-label="Permalink to &quot;解决的痛点&quot;">​</a></h3><p><strong>痛点1</strong>：以前你可能是这样做的，手动一个个打开Excel文件，然后依次设置密码。100个文件要花半小时，眼睛都看花了。</p><p><strong>用这个工具后</strong>：拖进来，点一下开始，1分钟全部搞定，100个文件同时加密，一个都不用你手动操作。</p><p><strong>痛点2</strong>：以前做法，给别人发文件前要把每个文件的密码记下来，然后通过其他方式告诉对方，特别麻烦。</p><p><strong>用这个工具后</strong>：批量设置统一密码，所有文件用同一个密码管理，省心又省力。</p><p><strong>痛点3</strong>：以前做法，要加密的文件夹里有子文件夹，不知道怎么一起处理，只能一个个文件夹进去找。</p><p><strong>用这个工具后</strong>：勾选穿透子文件夹选项，不管文件夹里有多少层子文件夹，所有Excel文件全部一起加密。</p><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><h3 id="场景1-年底加密所有财务报表" tabindex="-1">场景1：年底加密所有财务报表 <a class="header-anchor" href="#场景1-年底加密所有财务报表" aria-label="Permalink to &quot;场景1：年底加密所有财务报表&quot;">​</a></h3><p>场景描述：年底了，财务部门需要把全年12个月的财务报表全部加密，防止敏感数据泄露。每个月的报表分别在1月、2月…12月的子文件夹中。</p><p>操作步骤。</p><p><strong>第一步</strong>，在输入路径框中拖入整个年度报表文件夹。</p><p><strong>第二步</strong>，勾选<strong>穿透子文件夹</strong>和<strong>保持原文件夹结构</strong>。</p><p><strong>第三步</strong>，勾选<strong>添加查看密码</strong>，输入一个统一的年报查看密码。</p><p><strong>第四步</strong>，留空输出路径（这样会覆盖原文件），点击<strong>开始加密</strong>。</p><p>预期结果：程序自动遍历所有12个月份的子文件夹，找到所有Excel文件并加密。每个月份文件夹中会生成一个加密版文件夹，加密后的文件全部统一密码保护。</p><hr><h3 id="场景2-批量加密后保存到新位置" tabindex="-1">场景2：批量加密后保存到新位置 <a class="header-anchor" href="#场景2-批量加密后保存到新位置" aria-label="Permalink to &quot;场景2：批量加密后保存到新位置&quot;">​</a></h3><p>场景描述：要给客户发送一批加密文件，但不想改动自己电脑上的原始文件，想把加密后的版本单独保存。</p><p>操作步骤。</p><p><strong>第一步</strong>，拖入原始文件夹到输入路径。</p><p><strong>第二步</strong>，点击输出路径的<strong>浏览按钮</strong>，选择一个新的空文件夹作为输出位置。</p><p><strong>第三步</strong>，设置好查看密码和编辑密码。</p><p><strong>第四步</strong>，勾选保持原文件夹结构，点击<strong>开始加密</strong>。</p><p>预期结果：原文件夹完全不受影响，输出位置会生成一份一模一样的目录结构，只是所有Excel文件都带上了密码保护。</p><hr><h3 id="场景3-单文件快速加密" tabindex="-1">场景3：单文件快速加密 <a class="header-anchor" href="#场景3-单文件快速加密" aria-label="Permalink to &quot;场景3：单文件快速加密&quot;">​</a></h3><p>场景描述：临时需要给一个Excel文件加个密码，快速搞定就走。</p><p>操作步骤。</p><p><strong>第一步</strong>，直接把Excel文件<strong>拖入</strong>输入框。</p><p><strong>第二步</strong>，勾选查看密码，输入密码。</p><p><strong>第三步</strong>，留空输出路径（覆盖原文件），点击<strong>开始加密</strong>。</p><p>预期结果：几秒钟后，原文件直接变成加密状态，再次打开就需要输入密码了。</p><hr><h3 id="数据存储位置" tabindex="-1">数据存储位置 <a class="header-anchor" href="#数据存储位置" aria-label="Permalink to &quot;数据存储位置&quot;">​</a></h3><p><strong>输入文件</strong>：保存在你电脑原来的位置，程序不会移动或删除原始文件。</p><p><strong>输出文件（指定输出目录时）</strong>：保存在你选择的输出文件夹中，保持原目录结构。</p><p><strong>临时文件</strong>：处理过程中会在系统临时目录创建临时工作文件，处理完成后自动清理。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="问题1-程序提示未检测到office或wps-无法加密" tabindex="-1">问题1：程序提示未检测到Office或WPS，无法加密 <a class="header-anchor" href="#问题1-程序提示未检测到office或wps-无法加密" aria-label="Permalink to &quot;问题1：程序提示未检测到Office或WPS，无法加密&quot;">​</a></h3><p>答案：程序需要电脑安装Microsoft Office或WPS才能进行Excel加密。请确认电脑上是否已安装其中一款办公软件。如果没有安装，需要先安装Office或WPS才能使用加密功能。</p><hr><h3 id="问题2-加密后的文件打开显示密码错误" tabindex="-1">问题2：加密后的文件打开显示密码错误 <a class="header-anchor" href="#问题2-加密后的文件打开显示密码错误" aria-label="Permalink to &quot;问题2：加密后的文件打开显示密码错误&quot;">​</a></h3><p>答案：检查密码输入是否正确，注意密码<strong>区分大小写</strong>。如果不确定密码是什么，只能重新用原文件再次加密。如果原文件已删除，该文件将无法恢复。</p><hr><h3 id="问题3-勾选了穿透子文件夹但没有处理子文件夹中的文件" tabindex="-1">问题3：勾选了穿透子文件夹但没有处理子文件夹中的文件 <a class="header-anchor" href="#问题3-勾选了穿透子文件夹但没有处理子文件夹中的文件" aria-label="Permalink to &quot;问题3：勾选了穿透子文件夹但没有处理子文件夹中的文件&quot;">​</a></h3><p>答案：确认输入的是<strong>文件夹路径</strong>而不是文件路径。</p><p>如果输入的是单个Excel文件，即使勾选了穿透子文件夹也不会生效。另外检查是否正确勾选了<strong>穿透子文件夹</strong>选项。</p><hr><h3 id="问题4-输出文件夹中文件数量和原文件夹不一样" tabindex="-1">问题4：输出文件夹中文件数量和原文件夹不一样 <a class="header-anchor" href="#问题4-输出文件夹中文件数量和原文件夹不一样" aria-label="Permalink to &quot;问题4：输出文件夹中文件数量和原文件夹不一样&quot;">​</a></h3><p>答案：程序只会处理Excel文件（.xls、.xlsx、.xlsm、.xlsb），不会处理其他类型的文件。如果原文件夹有其他格式文件或损坏的Excel文件，这些不会被计入。</p><hr><h3 id="问题5-使用自动检测引擎加密失败" tabindex="-1">问题5：使用自动检测引擎加密失败 <a class="header-anchor" href="#问题5-使用自动检测引擎加密失败" aria-label="Permalink to &quot;问题5：使用自动检测引擎加密失败&quot;">​</a></h3><p>答案：可以手动切换引擎重试。如果电脑只装了WPS，选择WPS引擎；如果只装了Office，选择Office引擎。如果两种都装了但自动检测失败，轮流尝试两个引擎。</p><h1 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h1><p><strong>1、适用的系统环境说明</strong>：</p><p>win7及以上64位windows操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：</p><p>①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p>**3、程序如何安装：**不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h1 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h1><p><strong>解压后直接使用即可，不需要安装，快捷方式可以放在任意位置</strong>，和快捷方式一起的文件夹不要动</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-45.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2741.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2741.html</a></p>',104)])])}const f=e(i,[["render",o]]);export{d as __pageData,f as default};
